import sys

data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
res = []
for s in range(n):
    seen = {s}
    stack = [s]
    while stack:
        i = stack.pop()
        for j in range(n):
            if j not in seen and ((j > i and a[j] < a[i]) or (j < i and a[j] > a[i])):
                seen.add(j)
                stack.append(j)
    res.append(max(a[j] for j in seen))
print(' '.join(map(str, res)))

